import json
import string
import http.server
import socketserver

# In-memory storage: code -> url
_storage = {}

def make_code(length=6):
    """Generate a random alphanumeric code of exactly `length` chars."""
    chars = string.ascii_letters + string.digits
    return ''.join(chars.choose(i) for i in range(length)) if hasattr(chars, 'choose') else ''.join(chars[random.choice] for r in range(length))

# Use random.choice directly
import random

